import tags from "@/data/recipe-cards/catalog-tags.json";
import type { RecipeTags } from "@/lib/menu-generation/recipe-tags";
import { recipeTitleKey } from "./card";

// The nutritional tags of a catalogue recipe by exact title (N07; catalog-tags.json, generated by
// scripts/build-catalog-tags.cjs). Null for a dish outside the catalogue. Estimates pending review.
let index: Map<string, RecipeTags> | null = null;

export function catalogTags(title: string): RecipeTags | null {
  index ??= new Map(
    Object.entries((tags as unknown as { recipes: Record<string, RecipeTags> }).recipes).map(([name, value]) => [recipeTitleKey(name), value]),
  );
  return index.get(recipeTitleKey(title)) ?? null;
}
